"""Temp script: end-to-end sanity check of als_compressed after the rewrite."""
import torch
from einops import einsum
from hofft.decomp import als_compressed

torch.manual_seed(0)
dev = torch.device('cuda:1' if torch.cuda.is_available() else 'cpu')
dtype = torch.complex64

L, K, Q = 5, 5, 50
im_size = (32, 32, 32)

ck_true = torch.randn(L, K, Q, dtype=dtype, device=dev)
kern = torch.randn(K, *im_size, dtype=dtype, device=dev)
sf_true = torch.randn(L, *im_size, dtype=dtype, device=dev)

# Ground-truth spatial bases generated by the model: b[q,n] = sum_{l,k} sf[l,n] kern[k,n] ck[l,k,q]
sb = einsum(sf_true, kern, ck_true, 'L ..., K ..., L K Q -> Q ...')

# Mask with some zeroed voxels to exercise the singular-voxel path
mask = (torch.rand(im_size, device=dev) > 0.1).to(dtype)
sf_init = sf_true + 0.5 * torch.randn_like(sf_true)


def resid(sf, ck):
    approx = einsum(sf, kern, ck, 'L ..., K ..., L K Q -> Q ...')
    d = (approx - sb) * mask
    return (d.norm() / (sb * mask).norm()).item()


sf, ck = als_compressed(sb, kern, sf_init, mask=mask, max_iter=15, verbose=True)
print(f'init resid: {resid(sf_init, ck_true):.3e}')
print(f'final resid: {resid(sf, ck):.3e}')
assert resid(sf, ck) < 1e-3, 'ALS did not converge to model fit'
print('OK')
